use std::io::Write;
use std::net::TcpListener;
use std::env;

fn main() {
    let port = env::var("APP_PORT").unwrap_or_else(|_| "8080".to_string());
    let addr = format!("0.0.0.0:{}", port);
    let listener = TcpListener::bind(&addr).expect("Falha ao vincular porta");
    println!("Servidor Rust ouvindo em {}", addr);

    for stream in listener.incoming() {
        if let Ok(mut stream) = stream {
            let response_body = r#"{"status":"online","runtime":"Rust Latest","message":"ServApp Rust ativo no Cosmos-Server"}"#;
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                response_body.len(),
                response_body
            );
            let _ = stream.write_all(response.as_bytes());
        }
    }
}
